CREATE TABLE `t_friend_remark`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `me_id` bigint NOT NULL COMMENT '谁起的备注（t_user.id）',
  `friend_id` bigint NOT NULL COMMENT '备注的是哪个好友（t_user.id）',
